2	 * Git-aware isolated operations: every unit runs on its own worktree/branch created from the operation's integration
3	 * tip, and a completed unit is committed and merged into an operation integration worktree before the scheduler sees it
4	 * as complete. The operator's checkout is never touched, and nothing here runs when the operation did not opt in
5	 * (`state.git` absent).
6	 *
7	 * Integration is the only place the operation writes Git history. It is idempotent: a recorded receipt, or a branch
8	 * whose tip is already an ancestor of the integration branch, is recognised on resume, so a crash between the merge and
9	 * the persisted transition does not merge twice. A textual conflict aborts the merge, leaves both branches intact, and
10	 * returns a decision for the operator. A mechanically clean merge whose merged tree fails the unit's verifier is reset
11	 * and reported as an integration failure.
12	 */
13	import { execFileSync } from "node:child_process";
14	import { createHash } from "node:crypto";
15	import * as fs from "node:fs";
16	import * as path from "node:path";
17	import { ensureGitExclude } from "./git_exclude.js";
18	import { verifierTimeoutSecs } from "../tester.js";
19	import type {
20	  IntegrationReceipt,
21	  OperationGitState,
22	  OperationGitUnit,
