34	  try {
35	    const stdout = execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: GIT_TIMEOUT_MS });
36	    return { ok: true, stdout, stderr: "" };
37	  } catch (error: any) {
38	    return { ok: false, stdout: String(error?.stdout ?? ""), stderr: String(error?.stderr ?? error?.message ?? "") };
39	  }
40	}
41	
42	/** Filesystem- and ref-safe name; the hash keeps two ids that sanitise the same apart. */
43	export function gitSlug(value: string): string {
44	  const clean = value.toLowerCase().replace(/[^a-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "unit";
45	  return `${clean}-${createHash("sha256").update(value).digest("hex").slice(0, 8)}`;
