58	/** Where the operation's worktrees live, and what it integrates into. Reads Git; writes nothing. */
59	export function planOperationGit(workspace: string, operationId: string, baseRef = "HEAD"): OperationGitPlan {
60	  let repoRoot: string;
61	  try {
62	    repoRoot = git(workspace, ["rev-parse", "--show-toplevel"]);
63	  } catch {
64	    throw new Error(`git isolation needs a Git repository (${workspace} is not one)`);
65	  }
