1	/**
2	 * Slash commands the live TUI runs through the sidecar. The list mirrors the readline REPL (`cli/src/repl.ts`);
3	 * the TUI builds completion and help from `usage` and `summary`, so both are operator-facing text.
4	 */
5	import type { ConfirmHandler } from "../agent.js";
6	import type { CheckpointManager } from "../checkpoint.js";
7	import type { ApplicationCore } from "../core/app.js";
8	import type { ReceiptSection } from "../evidence.js";
9	import type { ApprovalMode } from "../types.js";
10	
11	export interface SlashSpec {
12	  name: string;
13	  usage: string;
14	  summary: string;
15	  aliases?: string[];
16	  /** Cancel stops it. Commands that resolve to a turn become cancellable when the turn starts. */
17	  cancellable?: boolean;
18	}
19	
20	/** What the sidecar lets a command read and change. */
21	export interface SlashHost {
22	  readonly app: ApplicationCore;
23	  mode(): ApprovalMode;
24	  setMode(mode: ApprovalMode): void;
25	  sessionId(): string;
26	  setSessionId(id: string): void;
27	  checkpoints(): CheckpointManager;
28	  setWorkspace(dir: string): void;
29	  saveSession(title?: string): void;
30	  resumeSession(id?: string): { ok: boolean; message: string };
31	  /** Earlier prompts, oldest first: the REPL history file, then this session's prompts. */
32	  history(): string[];
33	  /** Approval callback for agent runs a command starts; undefined in auto mode. */
34	  confirm(signal: AbortSignal): ConfirmHandler | undefined;
35	  /** Direct deliberate approval request for gated actions (such as in-place upgrades). */
36	  requestApproval?(tool: string, args: Record<string, any>, signal: AbortSignal): Promise<boolean>;
37	  /** Receipt sections for the last turn and the active validation receipt. */
38	  receipt(): ReceiptSection[];
39	}
40	
41	export interface SlashContext {
42	  host: SlashHost;
43	  args: string;
44	  signal: AbortSignal;
45	}
46	
47	export interface SlashReply {
48	  kind: "reply";
49	  command: string;
50	  success: boolean;
51	  output: string;
52	  /** "diff" asks the client to colour unified-diff lines. */
53	  format?: "diff";
54	  /** Text for the client to put into the composer. */
55	  composer?: string;
56	}
57	
58	/** The command resolved to a prompt: the sidecar checkpoints, then runs it as a turn under the command's id. */
59	export interface SlashTurn {
60	  kind: "turn";
61	  command: string;
62	  prompt: string | any[];
63	  label: string;
64	  checkpoint: string;
65	}
66	
67	export type SlashOutcome = SlashReply | SlashTurn;
68	export type SlashHandler = (ctx: SlashContext) => SlashOutcome | Promise<SlashOutcome>;
69	
70	export const NOT_A_REPO = "This workspace is not inside a git repository.";
71	
72	export function reply(command: string, output: string, success = true, extra: Pick<SlashReply, "format" | "composer"> = {}): SlashReply {
73	  return { kind: "reply", command, success, output, ...extra };
74	}
75	
76	export function errorText(err: unknown): string {
