1	import { execFileSync } from "node:child_process";
2	import * as fs from "node:fs";
3	import * as os from "node:os";
4	import * as path from "node:path";
5	import { copyToClipboard, readFromClipboard } from "../clipboard.js";
6	import { commitChanges, generateConventionalCommit, getGitInfo } from "../git.js";
7	import { HunkStager } from "../stager.js";
8	import { runTestSuiteWithExecutor, discoverVerifier, describeVerifier, verifierTimeoutSecs } from "../tester.js";
9	import { isWorkspaceTrusted } from "../workspace_trust.js";
10	import { PolicyContext } from "../core/approval_policy.js";
11	import { NOT_A_REPO, SlashContext, SlashHandler, SlashOutcome, errorText, reply } from "./catalog.js";
12	
13	function git(cwd: string, args: string[]): string {
14	  return execFileSync("git", args, { cwd, encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"], maxBuffer: 64 * 1024 * 1024 });
15	}
16	
17	function workspace(ctx: SlashContext): string {
18	  return ctx.host.app.getConfig().workspace;
19	}
20	
21	function diff(ctx: SlashContext): SlashOutcome {
22	  const cwd = workspace(ctx);
23	  if (!getGitInfo(cwd).isRepo) return reply("diff", NOT_A_REPO, false);
24	  try {
25	    const out = git(cwd, ["diff", "--no-color"]);
26	    return out.trim() ? reply("diff", out.trimEnd(), true, { format: "diff" }) : reply("diff", "Working tree clean: no uncommitted changes.");
27	  } catch (err) {
28	    return reply("diff", `git diff failed: ${errorText(err)}`, false);
29	  }
30	}
31	
32	function gitStatus(ctx: SlashContext): SlashOutcome {
33	  const cwd = workspace(ctx);
34	  if (!getGitInfo(cwd).isRepo) return reply("git", NOT_A_REPO, false);
35	  try {
36	    return reply("git", git(cwd, ["status", "--short"]).trimEnd() || "Working tree clean.");
37	  } catch (err) {
38	    return reply("git", `git status failed: ${errorText(err)}`, false);
39	  }
40	}
41	
42	function stage(ctx: SlashContext): SlashOutcome {
43	  const cwd = workspace(ctx);
44	  if (!getGitInfo(cwd).isRepo) return reply("stage", NOT_A_REPO, false);
45	  const stager = new HunkStager(cwd);
46	  if (ctx.args.trim() === "reset") {
47	    stager.unstage();
48	    return reply("stage", "Unstaged all changes.");
49	  }
50	  const summary = stager.getStatusSummary();
51	  if (!summary.files.length) return reply("stage", "No unstaged hunks in the working tree.");
52	  const lines = [`${summary.files.length} modified files, ${summary.unstagedHunkCount} hunks`];
53	  for (const file of summary.files) {
54	    lines.push("", `${file.newPath} (${file.hunks.length} hunks)`);
55	    file.hunks.forEach((hunk, index) => {
56	      lines.push(`  [hunk ${index + 1}] ${hunk.header}`);
57	      lines.push(...hunk.lines.slice(0, 5).map((line) => `    ${line}`));
58	      if (hunk.lines.length > 5) lines.push(`    … ${hunk.lines.length - 5} more lines`);
59	    });
60	  }
61	  lines.push("", "Unstage with /stage reset, or commit with /commit.");
62	  return reply("stage", lines.join("\n"));
63	}
64	
65	function commit(ctx: SlashContext): SlashOutcome {
66	  const cwd = workspace(ctx);
67	  const info = getGitInfo(cwd);
68	  if (!info.isRepo) return reply("commit", NOT_A_REPO, false);
69	  if (info.dirtyCount === 0) return reply("commit", "Working tree clean: nothing to commit.");
70	  const message = ctx.args.trim();
71	  if (!message) {
72	    const suggestion = generateConventionalCommit(cwd);
73	    return reply(
74	      "commit",
75	      `${suggestion.files.length} changed files. Suggested message:\n  ${suggestion.message}\n\nThe composer now holds /commit with this message: edit it and press enter to commit.`,
76	      true,
77	      { composer: `/commit ${suggestion.message}` },
78	    );
79	  }
80	  const result = commitChanges(cwd, message);
81	  return result.success ? reply("commit", `Committed ${result.hash ?? ""}: ${message}`) : reply("commit", `Commit failed: ${result.error}`, false);
82	}
83	
84	function checkpoint(ctx: SlashContext): SlashOutcome {
85	  const manager = ctx.host.checkpoints();
86	  const [sub, ...rest] = ctx.args.trim().split(/\s+/).filter(Boolean);
87	  if (sub?.toLowerCase() === "diff") {
88	    const [id, base] = rest;
89	    if (!id) return reply("checkpoint", "Usage: /checkpoint diff <id> [base-id]", false);
90	    const result = manager.getDiff(id, base);
91	    if (!result.success) return reply("checkpoint", `Diff failed: ${result.error}`, false);
92	    return result.diff.trim()
93	      ? reply("checkpoint", result.diff.trimEnd(), true, { format: "diff" })
94	      : reply("checkpoint", `No changes between ${id} and ${base ?? "the working tree"}.`);
95	  }
96	  if (sub?.toLowerCase() === "prune") {
97	    const keep = Number.parseInt(rest[0] ?? "20", 10);
98	    return reply("checkpoint", manager.pruneCheckpoints(Number.isNaN(keep) ? 20 : keep).message);
99	  }
100	  const created = manager.createCheckpoint(ctx.args.trim() || undefined);
101	  return reply("checkpoint", `Checkpoint saved: ${created.name} (${created.id})`);
102	}
103	
104	function checkpoints(ctx: SlashContext): SlashOutcome {
105	  const list = ctx.host.checkpoints().listCheckpoints();
106	  if (!list.length) return reply("checkpoints", "No saved checkpoints.");
107	  const rows = list.map((cp, index) => `${index + 1}. ${cp.id}  ${cp.name}  (${cp.timestamp})`);
108	  return reply("checkpoints", [...rows, "", "Compare with /checkpoint diff <id>, roll back with /undo."].join("\n"));
109	}
110	
111	function undo(ctx: SlashContext): SlashOutcome {
112	  const result = ctx.host.checkpoints().rollbackLast();
113	  return reply("undo", result.message, result.success);
114	}
115	
116	function worktree(ctx: SlashContext): SlashOutcome {
117	  const agent = ctx.host.app.getAgent();
118	  const active = agent.getActiveWorktree();
119	  const sub = ctx.args.trim().toLowerCase();
120	  if (sub === "merge" || sub === "discard") {
121	    if (!active) return reply("worktree", `No active speculative worktree to ${sub}.`, false);
122	    if (sub === "merge") {
123	      const result = agent.mergeActiveWorktree();
124	      return result.success
125	        ? reply("worktree", `Merged ${result.commitsMerged} speculative commit(s) from ${result.branch}.`)
126	        : reply("worktree", `Merge failed: ${result.error}`, false);
127	    }
128	    const result = agent.discardActiveWorktree();
129	    return result.success ? reply("worktree", "Discarded the active speculative worktree.") : reply("worktree", `Discard failed: ${result.error}`, false);
130	  }
131	  const lines: string[] = [];
132	  if (active) lines.push(`* active: ${active.branch} at ${active.worktreePath}`);
133	  lines.push(...agent.getWorktreeManager().listWorktrees().map((wt) => `• ${wt.taskId}  ${wt.branch}  ${wt.path}`));
134	  return reply("worktree", lines.length ? lines.join("\n") : "No speculative worktrees. Start Nexus with --worktree to isolate changes.");
135	}
136	
137	function audit(ctx: SlashContext): SlashOutcome {
138	  const file = path.join(os.homedir(), ".nexus", "audit.log");
